#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int u;
    int v;
    int w;
} Edge;

int cmp_edges(const void *a, const void *b) {
    int wa = ((const Edge *)a)->w;
    int wb = ((const Edge *)b)->w;
    return (wa > wb) - (wa < wb);
}

int find_set(int v, int *parent) {
    if (v == parent[v])
        return v;
    return parent[v] = find_set(parent[v], parent);
}

void dfs(int u, int *left_child, int *right_child, int *weight, long long *sum, long long *ans, long long parent_ans) {
    if (left_child[u] == 0) { // Folha
        ans[u] = parent_ans;
        return;
    }

    int l = left_child[u];
    int r = right_child[u];

    long long ans_l = (sum[l] >= weight[u]) ? parent_ans : sum[l];
    dfs(l, left_child, right_child, weight, sum, ans, ans_l);

    long long ans_r = (sum[r] >= weight[u]) ? parent_ans : sum[r];
    dfs(r, left_child, right_child, weight, sum, ans, ans_r);
}

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    int total_cells = n * m;

    int *p = (int *)malloc((total_cells + 1) * sizeof(int));
    for (int i = 1; i <= total_cells; i++) {
        scanf("%d", &p[i]);
    }

    int max_edges = 2 * total_cells;
    Edge *edges = (Edge *)malloc(max_edges * sizeof(Edge));
    int edge_count = 0;

    for (int r = 0; r < n; r++) {
        for (int c = 0; c < m; c++) {
            int u = r * m + c + 1;
            // Vizinho à direita
            if (c + 1 < m) {
                int v = r * m + (c + 1) + 1;
                int w = p[u] > p[v] ? p[u] : p[v];
                edges[edge_count++] = (Edge){u, v, w};
            }
            // Vizinho abaixo
            if (r + 1 < n) {
                int v = (r + 1) * m + c + 1;
                int w = p[u] > p[v] ? p[u] : p[v];
                edges[edge_count++] = (Edge){u, v, w};
            }
        }
    }

    qsort(edges, edge_count, sizeof(Edge), cmp_edges);

    int max_nodes = 2 * total_cells;
    int *dsu_parent = (int *)malloc(max_nodes * sizeof(int));
    int *left_child = (int *)calloc(max_nodes, sizeof(int));
    int *right_child = (int *)calloc(max_nodes, sizeof(int));
    int *node_weight = (int *)calloc(max_nodes, sizeof(int));
    long long *sum = (long long *)calloc(max_nodes, sizeof(long long));
    long long *ans = (long long *)malloc(max_nodes * sizeof(long long));

    for (int i = 1; i <= total_cells; i++) {
        dsu_parent[i] = i;
        sum[i] = p[i];
    }

    int cur_nodes = total_cells;
    for (int i = 0; i < edge_count; i++) {
        int root_u = find_set(edges[i].u, dsu_parent);
        int root_v = find_set(edges[i].v, dsu_parent);

        if (root_u != root_v) {
            cur_nodes++;
            dsu_parent[cur_nodes] = cur_nodes;
            dsu_parent[root_u] = cur_nodes;
            dsu_parent[root_v] = cur_nodes;

            left_child[cur_nodes] = root_u;
            right_child[cur_nodes] = root_v;
            node_weight[cur_nodes] = edges[i].w;
            sum[cur_nodes] = sum[root_u] + sum[root_v];
        }
    }

    int root = cur_nodes;
    dfs(root, left_child, right_child, node_weight, sum, ans, sum[root]);

    for (int r = 0; r < n; r++) {
        for (int c = 0; c < m; c++) {
            int id = r * m + c + 1;
            if (c > 0) printf(" ");
            printf("%lld", ans[id]);
        }
        printf("\n");
    }

    free(p);
    free(edges);
    free(dsu_parent);
    free(left_child);
    free(right_child);
    free(node_weight);
    free(sum);
    free(ans);

    return 0;
}
